{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, count(*) spans FROM abnormal_traces WHERE service_name='ts-travel2-service' GROUP BY 1,2 UNION ALL SELECT 'norm', service_name, count(*) FROM normal_traces WHERE service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "ts-travel2-service emitted 146 spans in the normal period and none in the abnormal period."
        },
        {
          "kind": "log",
          "sql": "SELECT 'abn' p, service_name, level, count(*) n, max(time) t1 FROM abnormal_logs WHERE service_name='ts-travel2-service' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, level, count(*), max(time) FROM normal_logs WHERE service_name='ts-travel2-service' GROUP BY 1,2,3",
          "claim": "ts-travel2-service logged 824 INFO lines in normal, none in abnormal; its logs stop at the window start."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, attr_k8s_pod_name pod, date_trunc('minute', time) m, round(avg(value),2) v FROM abnormal_metrics_sum WHERE attr_k8s_pod_name LIKE 'ts-travel2-service%' AND metric='container.cpu.time' GROUP BY 1,2,3 ORDER BY 3",
          "claim": "Travel2 pod container CPU time stays near 0.05 through the abnormal window, versus ~450 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT pc.service_name, pc.span_name, pc.attr_status_code, count(*) n, round(quantile_cont(pc.duration,0.5)/1e6,1) p50_ms FROM abnormal_traces pc WHERE pc.service_name='ts-route-plan-service' AND pc.attr_span_kind='Client' AND pc.span_name='POST' AND NOT EXISTS (SELECT 1 FROM abnormal_traces c WHERE c.parent_span_id=pc.span_id AND c.trace_id=pc.trace_id AND c.attr_span_kind='Server') GROUP BY 1,2,3",
          "claim": "54 route-plan POST client calls have no server span in the callee and fail after about 3.6 s median."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT pc.service_name, count(*) n, sum(CASE WHEN pc.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces pc WHERE pc.service_name='ts-route-plan-service' AND pc.attr_span_kind='Server' GROUP BY 1",
          "claim": "All 54 route-plan server spans in the abnormal window are errors, while route-plan's calls to travel2 go unanswered."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, count(*) spans, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Travel-plan's server spans are all errors with about 60 s p95, after route-plan's errors start."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, count(*) spans, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Ui-dashboard server spans show 30 errors out of 161, with p95 near 3.7 s, versus 0 errors and 302 ms in normal."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1,2,3",
          "claim": "Ui-dashboard's POST to travel2 trips/left failed in 30 of 36 spans, p95 about 3.9 s."
        }
      ]
    }
  ]
}
